import unittest
import mock
from mock import patch
from taf.ul.oam.selenium_coam.pages.common_page import CommonPage


class TestPageManager(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.CustomWebdriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        view_page = mock.Mock()
        view_page.MENU_ROUTE_LIST = mock.Mock()
        self.page_manager = CommonPage({"page_name": view_page})

    def test_get_page_instance(self):
        view_page_name = "page_name"

        view_page = mock.Mock()
        view_page.MENU_ROUTE_LIST = mock.Mock()
        self.page_manager._menu.open_page = mock.Mock()

        self.page_manager.open_page_and_get_instance(view_page_name)
        self.page_manager._menu.open_page.assert_called_once()
